namespace sv_dd170486ccbe42819ef12fa839a13a99.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped (per-circuit) service that holds theme state and notifies subscribers on change.
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    public void SetTheme(ThemeMode theme, string accentColor)
    {
        _theme = theme;
        _accentColor = accentColor;
        NotifyChanged();
    }

    private void NotifyChanged() => OnChange?.Invoke();
}

@using sv_dd170486ccbe42819ef12fa839a13a99.Services
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<span class="badge rounded-pill" style="background-color: @ThemeService.AccentColor; color: white;">
    @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@using sv_dd170486ccbe42819ef12fa839a13a99.Services
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme" title="Toggle theme">
    @GetIcon()
</button>

@code {
    private static readonly ThemeMode[] Modes = [ThemeMode.Light, ThemeMode.Dark, ThemeMode.System];

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void CycleTheme()
    {
        var currentIndex = Array.IndexOf(Modes, ThemeService.Theme);
        ThemeService.Theme = Modes[(currentIndex + 1) % Modes.Length];
    }

    private string GetIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@using sv_dd170486ccbe42819ef12fa839a13a99.Services
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <div class="mb-3">
            <label class="form-label">Theme</label>
            <select class="form-select" @bind="SelectedTheme">
                <option value="@ThemeMode.Light">Light</option>
                <option value="@ThemeMode.Dark">Dark</option>
                <option value="@ThemeMode.System">System</option>
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <input type="color" class="form-control form-control-color"
                   @bind="SelectedAccentColor" />
        </div>

        <button class="btn btn-primary" @onclick="Save">Save Preferences</button>
    </div>
</div>

<p class="mt-3 text-muted">
    Current: <strong>@ThemeService.Theme</strong> &mdash;
    Accent: <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
</p>

@code {
    private ThemeMode SelectedTheme { get; set; }
    private string SelectedAccentColor { get; set; } = string.Empty;

    protected override void OnInitialized()
    {
        SelectedTheme = ThemeService.Theme;
        SelectedAccentColor = ThemeService.AccentColor;
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void Save()
    {
        ThemeService.SetTheme(SelectedTheme, SelectedAccentColor);
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(() =>
        {
            SelectedTheme = ThemeService.Theme;
            SelectedAccentColor = ThemeService.AccentColor;
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

