@page "/settings"
@using sv_dd170486ccbe42819ef12fa839a13a99.Services
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <div class="mb-3">
            <label class="form-label">Theme</label>
            <select class="form-select" @bind="SelectedTheme">
                <option value="@ThemeMode.Light">Light</option>
                <option value="@ThemeMode.Dark">Dark</option>
                <option value="@ThemeMode.System">System</option>
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <input type="color" class="form-control form-control-color"
                   @bind="SelectedAccentColor" />
        </div>

        <button class="btn btn-primary" @onclick="Save">Save Preferences</button>
    </div>
</div>

<p class="mt-3 text-muted">
    Current: <strong>@ThemeService.Theme</strong> &mdash;
    Accent: <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
</p>

@code {
    private ThemeMode SelectedTheme { get; set; }
    private string SelectedAccentColor { get; set; } = string.Empty;

    protected override void OnInitialized()
    {
        SelectedTheme = ThemeService.Theme;
        SelectedAccentColor = ThemeService.AccentColor;
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void Save()
    {
        ThemeService.SetTheme(SelectedTheme, SelectedAccentColor);
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(() =>
        {
            SelectedTheme = ThemeService.Theme;
            SelectedAccentColor = ThemeService.AccentColor;
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

